-- Rudrika by Tara: additive schema changes for a live database. Safe to re-run.
-- Take a pg_dump first. Then: psql "$DATABASE_URL" -f scripts/migrate-rudrika.sql
ALTER TABLE "User" ADD COLUMN IF NOT EXISTS "whatsappOptIn" BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE "User" ADD COLUMN IF NOT EXISTS "birthday" TIMESTAMP(3);
ALTER TABLE "User" ADD COLUMN IF NOT EXISTS "loyaltyPoints" INTEGER NOT NULL DEFAULT 0;
ALTER TABLE "User" ADD COLUMN IF NOT EXISTS "lifetimeSpend" INTEGER NOT NULL DEFAULT 0;
ALTER TABLE "User" ADD COLUMN IF NOT EXISTS "tier" TEXT NOT NULL DEFAULT 'Silver';
ALTER TABLE "User" ADD COLUMN IF NOT EXISTS "membershipExpiresAt" TIMESTAMP(3);
ALTER TABLE "Product" ADD COLUMN IF NOT EXISTS "productCode" TEXT;
ALTER TABLE "Product" ADD COLUMN IF NOT EXISTS "hsn" TEXT;
ALTER TABLE "Product" ADD COLUMN IF NOT EXISTS "gstRate" INTEGER NOT NULL DEFAULT 5;
ALTER TABLE "Product" ADD COLUMN IF NOT EXISTS "silkMark" BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE "Product" ADD COLUMN IF NOT EXISTS "preorder" BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE "Product" ADD COLUMN IF NOT EXISTS "earlyAccess" BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE "Product" ADD COLUMN IF NOT EXISTS "tags" TEXT NOT NULL DEFAULT '[]';
ALTER TABLE "Product" ADD COLUMN IF NOT EXISTS "collections" TEXT NOT NULL DEFAULT '[]';
ALTER TABLE "Product" ADD COLUMN IF NOT EXISTS "care" TEXT;
CREATE UNIQUE INDEX IF NOT EXISTS "Product_productCode_key" ON "Product"("productCode");
ALTER TABLE "Variant" ADD COLUMN IF NOT EXISTS "legacySku" TEXT;
ALTER TABLE "Order" ADD COLUMN IF NOT EXISTS "invoiceNumber" TEXT;
ALTER TABLE "Order" ADD COLUMN IF NOT EXISTS "invoiceDate" TIMESTAMP(3);
ALTER TABLE "Order" ADD COLUMN IF NOT EXISTS "pointsRedeemed" INTEGER NOT NULL DEFAULT 0;
ALTER TABLE "Order" ADD COLUMN IF NOT EXISTS "pointsValue" INTEGER NOT NULL DEFAULT 0;
ALTER TABLE "Order" ADD COLUMN IF NOT EXISTS "pointsEarned" INTEGER NOT NULL DEFAULT 0;
ALTER TABLE "Order" ADD COLUMN IF NOT EXISTS "membershipDiscount" INTEGER NOT NULL DEFAULT 0;
ALTER TABLE "Order" ADD COLUMN IF NOT EXISTS "whatsappOptIn" BOOLEAN NOT NULL DEFAULT true;
ALTER TABLE "Order" ADD COLUMN IF NOT EXISTS "courier" TEXT;
ALTER TABLE "Order" ADD COLUMN IF NOT EXISTS "awb" TEXT;
ALTER TABLE "Order" ADD COLUMN IF NOT EXISTS "packedAt" TIMESTAMP(3);
ALTER TABLE "Order" ADD COLUMN IF NOT EXISTS "shippedAt" TIMESTAMP(3);
ALTER TABLE "Order" ADD COLUMN IF NOT EXISTS "deliveredAt" TIMESTAMP(3);
ALTER TABLE "Order" ADD COLUMN IF NOT EXISTS "feedbackSentAt" TIMESTAMP(3);
ALTER TABLE "Order" ADD COLUMN IF NOT EXISTS "note" TEXT;
CREATE UNIQUE INDEX IF NOT EXISTS "Order_invoiceNumber_key" ON "Order"("invoiceNumber");
ALTER TABLE "OrderItem" ADD COLUMN IF NOT EXISTS "sku" TEXT;
ALTER TABLE "OrderItem" ADD COLUMN IF NOT EXISTS "hsn" TEXT;
ALTER TABLE "OrderItem" ADD COLUMN IF NOT EXISTS "gstRate" INTEGER;
ALTER TABLE "OrderItem" ADD COLUMN IF NOT EXISTS "preorder" BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE "Coupon" ADD COLUMN IF NOT EXISTS "customerId" TEXT;
ALTER TABLE "Coupon" ADD COLUMN IF NOT EXISTS "singleUse" BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE "Coupon" ADD COLUMN IF NOT EXISTS "note" TEXT;
CREATE TABLE IF NOT EXISTS "LoyaltyLedger" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "delta" INTEGER NOT NULL, "reason" TEXT NOT NULL, "orderId" TEXT, "note" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "LoyaltyLedger_userId_idx" ON "LoyaltyLedger"("userId");
CREATE TABLE IF NOT EXISTS "CustomerPhoto" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "productId" TEXT REFERENCES "Product"("id") ON DELETE SET NULL, "orderId" TEXT, "image" TEXT NOT NULL, "caption" TEXT, "consent" BOOLEAN NOT NULL DEFAULT false, "status" TEXT NOT NULL DEFAULT 'PENDING', "couponCode" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "reviewedAt" TIMESTAMP(3));
CREATE INDEX IF NOT EXISTS "CustomerPhoto_status_idx" ON "CustomerPhoto"("status");
CREATE INDEX IF NOT EXISTS "CustomerPhoto_productId_status_idx" ON "CustomerPhoto"("productId","status");
CREATE TABLE IF NOT EXISTS "Membership" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "orderId" TEXT, "startsAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "expiresAt" TIMESTAMP(3) NOT NULL, "pricePaid" INTEGER NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, "reminderSentAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "Membership_userId_idx" ON "Membership"("userId");
CREATE TABLE IF NOT EXISTS "Post" ("id" TEXT PRIMARY KEY, "slug" TEXT NOT NULL UNIQUE, "title" TEXT NOT NULL, "excerpt" TEXT, "body" TEXT NOT NULL, "cover" TEXT, "publishedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "published" BOOLEAN NOT NULL DEFAULT true, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "Collection" ("id" TEXT PRIMARY KEY, "handle" TEXT NOT NULL UNIQUE, "title" TEXT NOT NULL, "subtitle" TEXT, "image" TEXT, "sort" INTEGER NOT NULL DEFAULT 0, "enabled" BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS "WhatsAppLog" ("id" TEXT PRIMARY KEY, "event" TEXT NOT NULL, "to" TEXT NOT NULL, "template" TEXT, "text" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'QUEUED', "error" TEXT, "orderId" TEXT REFERENCES "Order"("id") ON DELETE SET NULL, "userId" TEXT REFERENCES "User"("id") ON DELETE SET NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "WhatsAppLog_event_status_idx" ON "WhatsAppLog"("event","status");
